function R({registerIndicator:f,sourceValues:M,nulls:y}){f({id:"oa-rmed",name:"Ehlers Recursive Median Filter (RMED)",category:"Filters",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:12,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"rmed",type:"line",title:"RMED",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,c){const s=n.length,b=Math.max(1,Math.floor(Number(c.period)||12)),i=M(n,c.source??"close"),m=360/b,u=Math.cos(m*Math.PI/180),N=Math.sin(m*Math.PI/180);let e=(u+N-1)/u;Number.isNaN(e)&&(e=0),e=Math.max(0,Math.min(1,e));const d=[0,0,0,0,0],r=[0,0,0,0,0];let a=0,l=0;const h=new Array(s).fill(NaN);for(let t=0;t<s;t++){const p=Number.isFinite(i[t])?i[t]:0;d[a]=p,a=(a+1)%5;for(let o=0;o<5;o++)r[o]=d[o];r.sort((o,x)=>o-x);const k=r[2];l=t===0?p:e*k+(1-e)*l,h[t]=l}return{rmed:y(h)}}})}export{R as default};
